const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const text = JSON.stringify(payload).toLowerCase();

// Zero-Trust Non-PHI Check: Reject immediately if clinical PHI terms are present
const phiKeywords = ['prescription', 'diagnosis', 'symptom', 'treatment plan', 'blood test', 'biopsy', 'radiology', 'mri scan', 'ehr record', 'patient record', 'hiv', 'oncology patient'];
const containsPhi = phiKeywords.some(keyword => text.includes(keyword));

const facilityId = String(payload.facilityId || payload.facility_id || '').trim();
const facilityName = String(payload.facilityName || payload.hospitalName || '').trim();
const registrationNumber = String(payload.registrationNumber || payload.licenseNumber || '').trim();
const facilityType = String(payload.facilityType || 'Multi-Specialty Hospital').trim();
const bedCapacity = Number(payload.bedCapacity || payload.bedCount || 0);
const adminEmail = String(payload.adminEmail || payload.email || '').trim().toLowerCase();
const state = String(payload.state || 'Tamil Nadu').trim();
const nabhAccredited = Boolean(payload.nabhAccredited || payload.nabh);

const isValidFacility = Boolean(facilityId && facilityName && adminEmail.includes('@') && !containsPhi);

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    containsPhi,
    isValidFacility,
    facility: {
      facilityId,
      facilityName,
      registrationNumber,
      facilityType,
      bedCapacity,
      adminEmail,
      state,
      nabhAccredited,
      onboardedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const fac = item.facility;
const cleanId = fac.facilityId.replace(/[^a-zA-Z0-9]/g, '').substring(0, 12).toLowerCase();
const tenantSchema = `tenant_hospital_${cleanId}`;

const integrationSpecs = {
  tenantSchema,
  databaseIsolationMode: 'Row-Level Security with Dedicated Schema Partition',
  abdmGatewayReady: true,
  fhirVersion: 'HL7 FHIR Release 4 (R4)',
  modulesProvisioned: ['OPD', 'IPD', 'Billing', 'Pharmacy', 'Inventory', 'Lab-LIS', 'Radiology-RIS'],
  initialAdminAccount: fac.adminEmail,
  complianceStandard: 'HIPAA Security Rule & DPDP Act 2023',
  leadEngineerSignoff: 'Vikash Saravanan (Lead System Engineer)'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'facility_tenant_provisioned',
    detail: {
      facilityId: fac.facilityId,
      facilityName: fac.facilityName,
      integrationSpecs,
      provisionedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
return [{
  json: {
    eventId: item.eventId,
    status: 'facility_onboarding_rejected',
    error: item.containsPhi
      ? 'CRITICAL_SECURITY_BREACH: Prohibited PHI clinical data detected in facility onboarding payload'
      : 'Invalid facility parameters: missing facilityId, facilityName, or valid adminEmail'
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
